<?php
                $tenants = rows($pdo, "SELECT id, full_name FROM tenants WHERE status='active' ORDER BY full_name");
                $rooms = rows($pdo, "SELECT rm.id, rm.room_number, rm.monthly_rate, b.name AS building_name FROM rooms rm JOIN kos_buildings b ON b.id=rm.building_id WHERE rm.status='available' AND b.status='active' AND NOT EXISTS (SELECT 1 FROM rentals r WHERE r.room_id=rm.id AND r.status IN ('active','upcoming') AND (r.end_date IS NULL OR r.end_date>=CURDATE())) ORDER BY b.name, rm.room_number");
            ?>
                <div class="form-panel"><div class="panel-heading"><div><h2>Catat sewa baru</h2><p>Pilih pelanggan dan kamar untuk memulai masa sewa.</p></div><a class="text-link" href="index.php?page=rentals">← Kembali</a></div>
                    <?php if (!$tenants || !$rooms): ?><div class="alert error">Untuk membuat sewa, siapkan minimal satu pelanggan aktif dan satu kamar yang tersedia.</div><?php else: ?><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="create_rental">
                    <label class="field"><span>Pelanggan *</span><select name="tenant_id" required><option value="">Pilih pelanggan</option><?php foreach ($tenants as $tenant): ?><option value="<?= (int) $tenant['id'] ?>"><?= e($tenant['full_name']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Gedung / kamar *</span><select name="room_id" id="room-select" required><option value="">Pilih gedung dan kamar</option><?php foreach ($rooms as $room): ?><option value="<?= (int) $room['id'] ?>" data-rate="<?= e($room['monthly_rate']) ?>"><?= e($room['building_name']) ?> · Kamar <?= e($room['room_number']) ?> — <?= e(money($room['monthly_rate'])) ?>/bulan</option><?php endforeach; ?></select></label>
                    <?php field('Mulai sewa *', 'start_date', date('Y-m-d'), 'date', ['required' => 'required']); field('Akhir sewa', 'end_date', '', 'date'); field('Tarif per bulan (Rp) *', 'monthly_rate', '', 'number', ['required' => 'required', 'min' => '1', 'step' => '1000', 'id' => 'rate-input']); field('Deposit (Rp)', 'deposit_amount', '0', 'number', ['min' => '0', 'step' => '1000']); field('Tanggal tagihan setiap bulan *', 'billing_day', '1', 'number', ['required' => 'required', 'min' => '1', 'max' => '28']); ?>
                    <label class="field full-span"><span>Catatan</span><textarea name="notes" rows="3"></textarea></label><div class="form-actions full-span"><a class="button secondary" href="index.php?page=rentals">Batal</a><button class="button primary" type="submit">Simpan masa sewa</button></div></form><?php endif; ?>
                </div>
            